from pathlib import Path
Path('verify-current-scope-regressions.mjs').write_text(r'''import fs from 'node:fs';import vm from 'node:vm';
const assert=(v,m)=>{if(!v)throw new Error(m)};globalThis.Event=globalThis.Event||class Event{constructor(type){this.type=type;}};globalThis.dispatchEvent=globalThis.dispatchEvent||(()=>true);for(const f of ['workbook.js','hash.js','workflow-schema.js','test-runtime.js','workflow-engine.js','prompt-engine.js','response-ingestion.js'])vm.runInThisContext(fs.readFileSync(f,'utf8'),{filename:f});
const core=globalThis.closedLoopCore,engine=globalThis.closedLoopWorkflowEngine,prompts=globalThis.closedLoopPromptEngine,ingestion=globalThis.closedLoopResponseIngestion,schema=globalThis.closedLoopWorkflowSchema;assert(core&&engine&&prompts&&ingestion&&schema,'scope runtime');const base=id=>{const p=core.createBlankState(id);Object.assign(p.job,{JOB_ID:id,JOB_TITLE:'Scope regression',EXACT_USER_OBJECTIVE_VERBATIM:'Prove stale data cannot govern current work.',EXPLICIT_USER_REQUIREMENTS:'Current scope only.',CURRENT_INPUT_VERSION:'INPUT-v001',CURRENT_SOURCE_SET_VERSION:'SOURCE-v001',CURRENT_REQUIREMENTS_VERSION:'REQ-v001',CURRENT_TEST_SUITE_VERSION:'TEST-v001',CURRENT_INSTRUCTION_VERSION:'INST-v001'});engine.ensureShape(p);return p},vs=p=>({inputVersion:p.job.CURRENT_INPUT_VERSION,sourceSetVersion:p.job.CURRENT_SOURCE_SET_VERSION,requirementsVersion:p.job.CURRENT_REQUIREMENTS_VERSION,testSuiteVersion:p.job.CURRENT_TEST_SUITE_VERSION,instructionVersion:p.job.CURRENT_INSTRUCTION_VERSION});
{const p=base('JOB-S11'),scope={...vs(p),iterationId:'ITER-INITIAL',candidateId:'CAND-INITIAL'};p.projectData.iterations.push({id:'ITER-INITIAL',stage:10,active:true,scope,fields:{ITERATION_ID:'ITER-INITIAL',CANDIDATE_ID:'CAND-INITIAL',STATUS:'FROZEN'}});p.projectData.candidateFreezes.push({id:'CAND-INITIAL',stage:10,active:true,scope,fields:{CANDIDATE_ID:'CAND-INITIAL',ITERATION_ID:'ITER-INITIAL',COMPONENT_HASHES:{A:'a'.repeat(64)},STATUS:'FROZEN'}});p.job.CURRENT_ITERATION='ITER-INITIAL';assert(engine.deriveStageData(p,11).ITERATION_ID==='ITER-INITIAL','Stage 11 lost Stage 10 iteration');}
{const p=base('JOB-S28'),cur={...vs(p),baselineId:'BASE-v1',productId:'PROD-v1'},old={...cur,productId:'PROD-OLD'};p.job.CURRENT_BASELINE_ID='BASE-v1';p.job.CURRENT_PRODUCT_ID='PROD-v1';p.projectData.artifactIdentities.push({id:'ID-OLD',stage:28,active:true,scope:old,fields:{IDENTITY_ID:'ID-OLD',AUTHORIZATION:'NOT AUTHORIZED',EXACT_HASH_MATCH:false,EXACT_SIZE_MATCH:false}},{id:'ID-CUR',stage:28,active:true,scope:cur,fields:{IDENTITY_ID:'ID-CUR',AUTHORIZATION:'AUTHORIZED',EXACT_HASH_MATCH:true,EXACT_SIZE_MATCH:true}});const r=engine.DERIVATIONS['stage28.artifactIdentity'](p).value;assert(r.count===1&&r.authorized,'Stage 28 admitted stale identity');}
{const p=base('JOB-S29'),cur={...vs(p),baselineId:'BASE-v1',productId:'PROD-v1'},old={...cur,requirementsVersion:'REQ-OLD'};p.job.CURRENT_BASELINE_ID='BASE-v1';p.job.CURRENT_PRODUCT_ID='PROD-v1';p.projectData.evidenceChains.push({id:'CHAIN-OLD',stage:29,active:true,scope:old,fields:{CHAIN_ID:'CHAIN-OLD',STATUS:'INCOMPLETE'}},{id:'CHAIN-CUR',stage:29,active:true,scope:cur,fields:{CHAIN_ID:'CHAIN-CUR',STATUS:'COMPLETE'}});const r=engine.DERIVATIONS['stage29.evidenceChains'](p).value;assert(r.count===1&&r.complete,'Stage 29 admitted stale chain');}
{let p=base('JOB-BLOCK');const pr=prompts.buildPromptRecord(1,p,{operation:'COMPLETE'});p.projectData.generatedPrompts.push(pr);const e={schema:schema.RESPONSE_SCHEMA,jobId:p.job.JOB_ID,stage:1,operation:'COMPLETE',promptIdentity:{instructionId:pr.instructionId,bodySha256:pr.bodySha256,contractSha256:pr.contractSha256,contextSignature:pr.contextSignature},scope:pr.scope,responseType:'BLOCKED',humanInputRequests:[],stageData:{},records:{},evidence:[],unresolved:[{temporaryKey:'missing-file',kind:'MISSING_ARTIFACT',description:'Required Stage 01 file bytes are absent from this agent context.',whyBlocking:'The first semantic reader cannot inspect missing bytes.',affectedStageFields:['INPUT_SET_CONTENTS'],affectedRecords:[],blocking:true}],warnings:[],attachments:[]};const prep=ingestion.prepare(p,{stage:1,text:JSON.stringify(e),promptRecord:pr});assert(prep.validation.valid,JSON.stringify(prep.validation.issues));p=ingestion.commit(prep.project,prep.proposal.proposalId,{operator:'SCOPE'}).project;const b=p.projectData.blockers.at(-1),id=engine.recordId(b,'blockers');assert(b.scope?.inputVersion===pr.scope.inputVersion,'blocker scope lost');assert(engine.openBlockers(p,1).some(x=>engine.recordId(x,'blockers')===id),'current blocker missing');p.job.CURRENT_INPUT_VERSION='INPUT-v002';assert(!engine.openBlockers(p,1).some(x=>engine.recordId(x,'blockers')===id),'stale blocker still controls');assert(p.projectData.blockers.some(x=>engine.recordId(x,'blockers')===id),'blocker history lost');}
console.log(JSON.stringify({currentScopeRegressions:'PASS',stage11IterationRoute:true,stage28CurrentIdentityOnly:true,stage29CurrentEvidenceChainsOnly:true,blockerScopePreservedAndStaleExcluded:true},null,2));
''')
